_AUTHORED_PREPARATION_KICKOFF = r"""const renderKickoff=()=>{const section=card('Kick off preparation','Preparation will begin in the workspace.');const notice=document.createElement('p');notice.className='notice';notice.textContent='Nothing in your library changes. Writes stay off until you turn them on in Activity.';const form=document.createElement('form');form.append(notice,button('Kick off preparation',true));form.addEventListener('submit',async event=>{event.preventDefault();try{const result=await api('/api/setup/kick-off',{method:'POST',body:JSON.stringify({expected_revision:state.revision}),mutation:true});section.replaceChildren();const heading=document.createElement('h2');heading.tabIndex=-1;heading.textContent='Preparation is starting';const copy=document.createElement('p');copy.textContent='Preparation continues safely in the normal workspace.';const safety=document.createElement('p');safety.className='notice';safety.textContent=result.message;const progress=document.createElement('div');renderPreparation(progress,null);section.append(heading,copy,safety,progress);heading.focus({preventScroll:true});let open=null;let observed=true;let announcedState=null;let stopped=false;let timer=null;let pollDelay=1500;const finishLedger=()=>{for(const row of ledger.querySelectorAll('.ledger-row')){row.removeAttribute('aria-current');row.querySelector('span').textContent='✓';row.querySelector('button')?.remove()}};const stop=()=>{stopped=true;if(timer!==null)clearTimeout(timer)};const retire=dismissed=>{stop();renderPreparation(progress,null);finishLedger();heading.textContent=dismissed?'Preparation was dismissed':'Preparation is no longer available';copy.textContent=dismissed?'Open the ordinary workspace.':'The preparation record is no longer available. Open the ordinary workspace.';progress.textContent='No preparation run is available.';if(!open){open=document.createElement('a');open.className='primary';open.textContent='Open workspace';section.append(open)}open.href='/library?lens=all';announce(heading.textContent)};const poll=async()=>{try{const response=await fetch('/api/v1/review-preparation',{credentials:'same-origin'});if(response.status===401){stop();finishLedger();heading.textContent='Sign in to continue';copy.textContent='Your setup sign-in expired while preparation continued safely. Sign in to the workspace to see live progress.';progress.textContent='Preparation continues in the normal workspace.';const signIn=document.createElement('a');signIn.href='/library?lens=all';signIn.textContent='Sign in to workspace';section.append(signIn);heading.focus({preventScroll:true});return}if(!response.ok)throw new Error('unavailable');const preparation=await response.json();const visible=preparation.presentation;const retired=visible?.state==='dismissed';if(!visible||retired){if(observed||retired)retire(retired);else renderPreparation(progress,null);return}observed=true;const confirmed=renderPreparation(progress,visible);if(!open){open=document.createElement('a');open.className='primary workspace-handoff';open.textContent='Open workspace';open.addEventListener('click',event=>{if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const target=new URL(open.href,location.href);const run=target.searchParams.get('preparation')??'';if(target.origin!==location.origin||target.pathname!=='/library'||!/^preparation_run_[0-9a-f]{64}$/.test(run))return;const motion=document.querySelector('#setup-handoff-motion');if(!(motion instanceof HTMLLinkElement))return;let fallback=null;const disable=()=>{motion.disabled=true;if(fallback!==null)clearTimeout(fallback)};motion.disabled=false;addEventListener('pageshow',disable,{once:true});addEventListener('pageswap',handoff=>{if(handoff.viewTransition)void handoff.viewTransition.finished.then(disable,disable);else disable()},{once:true});fallback=setTimeout(disable,2000)});section.append(open)}open.href=`/library?lens=all&preparation=${encodeURIComponent(visible.run_id)}`;finishLedger();const terminal=['completed_clean','completed_with_failures'].includes(visible.state);pollDelay=terminal?5000:1500;heading.textContent=visible.state==='blocked'?'Preparation needs attention':terminal?'Preparation is complete':'Preparation continues';copy.textContent=visible.state==='blocked'?'Open the workspace to review recovery while preparation remains safely paused.':terminal?'Open the workspace to review the completed preparation record.':'Open the workspace while preparation continues.';if(confirmed!==announcedState){announcedState=confirmed;announce(confirmed)}}catch{const confirmed=progress.querySelector('[role=status]');if(confirmed){confirmed.textContent='Reconnecting · showing the last confirmed state';announce('Reconnecting to preparation progress')}}finally{if(!stopped)timer=setTimeout(poll,pollDelay)}};timer=setTimeout(poll,1500)}catch(e){error(form,e.message)}});section.append(form)}"""


def _install_authored_preparation_kickoff(source: str) -> str:
    start_marker = "const renderKickoff=()=>{"
    end_marker = ";const render=async()=>"
    if source.count(start_marker) != 1 or source.count(end_marker) != 1:
        raise RuntimeError("setup preparation bridge boundary changed")
    start = source.index(start_marker)
    end = source.index(end_marker, start)
    return source[:start] + _AUTHORED_PREPARATION_KICKOFF + source[end:]


SETUP_JS = _install_authored_preparation_kickoff(SETUP_JS)

__all__ = ["SETUP_CSS", "SETUP_HTML", "SETUP_JS"]
